1	/**
2	 * `@pantoken/plugin-theme-custom-media` — author with theme custom-idents
3	 * (`@media (theme: <name>)`) and/or `@media (--theme-*)` aliases, then emit concrete CSS for a
4	 * chosen target theme.
5	 *
6	 * The plugin expands built-in `--theme-*` aliases, prunes non-target theme branches, strips
7	 * matching `theme:*` clauses from kept queries, unwraps always-true theme-only media wrappers, and
8	 * removes `@custom-media --theme-*` declarations from emitted CSS.
9	 *
10	 * @module
11	 * @beta
12	 */
13	import type { AtRule, Plugin } from "postcss";
14	
15	export type Theme = "rebrand" | "canvas" | "canvasHighContrast";
16	
17	export interface ThemeCustomMediaOptions {
18	  /** Target theme to emit (default `"rebrand"`). */
19	  theme?: Theme;
20	}
21	
22	const THEME_ALIAS = new Map<string, string>([
23	  ["--theme-rebrand", "(theme: rebrand)"],
24	  ["--theme-canvas", "(theme: canvas)"],
25	  ["--theme-canvas-high-contrast", "(theme: canvasHighContrast)"],
26	  ["--theme-light", "(theme: rebrand) and (prefers-color-scheme: light)"],
27	  ["--theme-dark", "(theme: rebrand) and (prefers-color-scheme: dark)"],
28	]);
29	
30	const THEME_FEATURE_RE = /\(\s*theme\s*:\s*(rebrand|canvas|canvasHighContrast)\s*\)/gu;
31	
32	const splitTopLevel = (input: string, separator: string): string[] => {
33	  const out: string[] = [];
34	  let depth = 0;
35	  let start = 0;
36	  for (let i = 0; i < input.length; i++) {
37	    const ch = input[i];
38	    if (ch === "(") depth++;
39	    else if (ch === ")" && depth > 0) depth--;
40	    else if (ch === separator && depth === 0) {
41	      out.push(input.slice(start, i).trim());
42	      start = i + 1;
43	    }
44	  }
45	  out.push(input.slice(start).trim());
46	  return out.filter(Boolean);
47	};
48	
49	const normalizeAndParts = (query: string): string => {
50	  const parts = splitTopLevel(query, ",");
51	  if (parts.length > 1) return parts.join(", ");
52	  const andParts = query
53	    .split(/\band\b/giu)
54	    .map((part) => part.trim())
55	    .filter(Boolean);
56	  return andParts.join(" and ").trim();
57	};
58	
59	interface QueryEval {
60	  keep: boolean;
61	  next: string;
62	}
63	
64	const evalQuery = (query: string, theme: Theme): QueryEval => {
65	  const themeMatches = Array.from(query.matchAll(THEME_FEATURE_RE)).map((m) => m[1]);
66	  if (themeMatches.length === 0) {
67	    return { keep: true, next: normalizeAndParts(query) };
68	  }
69	
70	  // If the query references another theme, this branch never applies for the selected target.
71	  if (themeMatches.some((name) => name !== theme)) {
72	    return { keep: false, next: "" };
73	  }
74	
75	  // Remove theme clauses for the target theme from the emitted output.
76	  const withoutTheme = query.replace(THEME_FEATURE_RE, "");
77	  const next = normalizeAndParts(withoutTheme)
78	    .replace(/^\s*and\s+/iu, "")
79	    .replace(/\s+and\s*$/iu, "")
80	    .trim();
81	
82	  return { keep: true, next };
83	};
84	
85	function lowerMedia(rule: AtRule, theme: Theme): void {
86	  const expanded = Array.from(THEME_ALIAS.entries()).reduce(
87	    (params, [alias, expr]) => params.replaceAll(`(${alias})`, expr),
88	    rule.params,
89	  );
90	
91	  const queries = splitTopLevel(expanded, ",");
92	  const kept = queries
93	    .map((q) => evalQuery(q, theme))
94	    .filter((q) => q.keep)
95	    .map((q) => q.next);
96	  if (kept.length === 0) {
97	    rule.remove();
98	    return;
99	  }
100	
101	  // If any query becomes unconditional, `@media` is always true for the target theme.
102	  if (kept.some((q) => q.length === 0)) {
103	    rule.replaceWith(...(rule.nodes ?? []));
104	    return;
105	  }
106	
107	  rule.params = kept.join(", ");
108	}
109	
110	/**
111	 * Create the theme custom-media lowering plugin.
112	 *
113	 * Supports authoring with either direct theme custom-idents in media features (for example,
114	 * `(theme: canvas)`) or built-in `@custom-media --theme-*` aliases.
115	 *
116	 * @param options - {@link ThemeCustomMediaOptions}.
117	 * @returns A PostCSS {@link Plugin}.
118	 */
119	export function themeCustomMedia(options: ThemeCustomMediaOptions = {}): Plugin {
120	  const theme = options.theme ?? "rebrand";
121	
122	  return {
123	    postcssPlugin: "pantoken-theme-custom-media",
124	    OnceExit(root) {
125	      root.walkAtRules("media", (rule) => lowerMedia(rule, theme));
126	
127	      // Remove authoring-time alias declarations from emitted CSS.
128	      root.walkAtRules("custom-media", (rule) => {
129	        const [alias] = rule.params.trim().split(/\s+/, 1);
130	        if (alias && THEME_ALIAS.has(alias)) rule.remove();
131	      });
132	    },
133	  };
134	}
135	
136	themeCustomMedia.postcss = true;
137	
138	export default themeCustomMedia;
139

1	import { expect, test } from "vite-plus/test";
2	import postcss from "postcss";
3	import { themeCustomMedia } from "../src/index.ts";
4	
5	const run = (css: string, theme: "rebrand" | "canvas" | "canvasHighContrast") =>
6	  postcss([themeCustomMedia({ theme })]).process(css, { from: undefined }).css;
7	
8	test("keeps only selected theme branches and unwraps always-true wrappers", () => {
9	  const css = [
10	    "@media (--theme-canvas) { .x { color: blue; } }",
11	    "@media (--theme-canvas-high-contrast) { .x { color: yellow; } }",
12	    "@media (--theme-rebrand) { .x { color: red; } }",
13	  ].join("\n");
14	
15	  const canvas = run(css, "canvas");
16	  expect(canvas).toContain(".x { color: blue; }");
17	  expect(canvas).not.toContain("yellow");
18	  expect(canvas).not.toContain("red");
19	  expect(canvas).not.toContain("@media");
20	});
21	
22	test("keeps prefers-color-scheme in rebrand light/dark branches", () => {
23	  const css = [
24	    "@media (--theme-light) { .x { color: white; } }",
25	    "@media (--theme-dark) { .x { color: black; } }",
26	    "@media (--theme-canvas) { .x { color: blue; } }",
27	  ].join("\n");
28	
29	  const out = run(css, "rebrand");
30	  expect(out).toContain("@media (prefers-color-scheme: light)");
31	  expect(out).toContain("@media (prefers-color-scheme: dark)");
32	  expect(out).not.toContain("theme:");
33	  expect(out).not.toContain("blue");
34	});
35	
36	test("drops theme @custom-media declarations from emitted css", () => {
37	  const out = run(
38	    "@custom-media --theme-canvas (theme: canvas);\n@custom-media --foo (width > 10px);\n@media (--theme-canvas) { .x { color: blue; } }",
39	    "canvas",
40	  );
41	  expect(out).not.toContain("@custom-media --theme-canvas");
42	  expect(out).toContain("@custom-media --foo");
43	  expect(out).toContain("color: blue");
44	});
