1	/**
2	 * Compile the `.css`-authored component records (`src/components/*.css`, `src/utilities/*.css`,
3	 * `src/rules/*.css`) into a single generated TS module of string constants
4	 * (`src/generated/component-styles.ts`). The `.css` files
5	 * are the authoring source of truth (real CSS — native stylelint/cssdoc/editor support); each carries the
6	 * `PFX-` class-prefix sentinel. The thin record wrappers import these consts and do
7	 * `raw.replaceAll(SENTINEL, p)` inside their `css: (p) => …` builder, so the prefix is applied at build
8	 * time exactly where `${p}` used to interpolate.
9	 *
10	 * Unlike the web-components `scripts/styles.ts` this module models, the cssdoc `/** … *\/` doc comments
11	 * are RETAINED — here they are load-bearing (they flow into `generated/components.css`, which
12	 * `docs/scripts/build-css-api.ts` parses for the CSS-API pages). Content is emitted verbatim; the runtime
13	 * pipeline (`define.ts`) normalizes leading/trailing whitespace, so byte-identity of the emitted sheets
14	 * is preserved.
15	 *
16	 * `vp pack` (rolldown) doesn't resolve Vite's `?raw` query, so a generated `.ts` module is the portable
17	 * way to get the CSS text into the published bundle. Run before `vp pack` / `generate` / `check` / `test`.
18	 */
19	import { mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
20	import { join, resolve } from "node:path";
21	import postcss from "postcss";
22	import { themeCustomMedia } from "@pantoken/plugin-theme-custom-media";
23	
24	const srcDir = resolve(import.meta.dirname, "../src");
25	const sources = [join(srcDir, "components"), join(srcDir, "utilities"), join(srcDir, "rules")];
26	const THEMES = ["rebrand", "canvas", "canvasHighContrast"] as const;
27	
28	/** `screen-reader-content.css` → `screenReaderContent`. */
29	const toIdentifier = (file: string): string =>
30	  file.replace(/\.css$/u, "").replace(/-([a-z0-9])/gu, (_m, c: string) => c.toUpperCase());
31	
32	const entries: string[] = [];
33	for (const dir of sources) {
34	  for (const file of readdirSync(dir)
35	    .filter((f) => f.endsWith(".css"))
36	    .sort()) {
37	    const css = readFileSync(join(dir, file), "utf8");
38	    const id = toIdentifier(file);
39	    const byTheme: Record<(typeof THEMES)[number], string> = {
40	      rebrand: css,
41	      canvas: css,
42	      canvasHighContrast: css,
43	    };
44	    for (const theme of THEMES) {
45	      byTheme[theme] = postcss([themeCustomMedia({ theme })]).process(css, { from: undefined }).css;
46	    }
47	    entries.push(`export const ${id}ByTheme = ${JSON.stringify(byTheme)} as const;`);
48	    entries.push(`export const ${id} = ${id}ByTheme.rebrand;`);
49	  }
50	}
51	
52	const outDir = join(srcDir, "generated");
53	mkdirSync(outDir, { recursive: true });
54	writeFileSync(
55	  join(outDir, "component-styles.ts"),
56	  `// AUTO-GENERATED from src/{components,utilities}/*.css by scripts/component-styles.ts — do not edit.\n${entries.join(
57	    "\n",
58	  )}\n`,
59	);
60	console.log(
61	  `✓ components: wrote src/generated/component-styles.ts (${String(entries.length)} stylesheets)`,
62	);
63

