1	/**
2	 * Shared state for the site-wide pantoken theme (rebrand / canvas / canvas high contrast). The palette
3	 * selector in the nav and the theme bootstrap in `index.ts` both go through {@link applyTheme}, so the
4	 * `<html data-pantoken-theme>` attribute, the `pantoken-theme` localStorage key, the light/dark gating,
5	 * and the demo-iframe broadcast stay in sync.
6	 *
7	 * `site-themes.css` scopes each theme's tokens to `:root[data-pantoken-theme="…"]`; toggling the
8	 * attribute re-themes the whole site (VitePress chrome via the `@pantoken/vitepress` bridge, the live
9	 * `@example` blocks, and — over postMessage — the embedded demos).
10	 */
11	export type PantokenTheme = "rebrand" | "canvas" | "canvasHighContrast";
12	
13	export interface ThemeOption {
14	  key: PantokenTheme;
15	  label: string;
16	}
17	
18	/**
19	 * Localized palette-selector strings, supplied per locale via `themeConfig.themeSelector`
20	 * (see `.vitepress/i18n.ts`) and read at runtime by {@link ThemeSelector}. `label` is the trigger
21	 * button's accessible name; the per-key labels name each palette. The English values here double as
22	 * the fallback when a locale omits the block.
23	 */
24	export interface ThemeSelectorStrings {
25	  label: string;
26	  rebrand: string;
27	  canvas: string;
28	  canvasHighContrast: string;
29	}
30	
31	/** English defaults, also the fallback when a locale doesn't localize the selector. */
32	export const THEME_SELECTOR_DEFAULTS: ThemeSelectorStrings = {
33	  label: "Select theme",
34	  rebrand: "Rebrand",
35	  canvas: "Canvas",
36	  canvasHighContrast: "Canvas high contrast",
37	};
38	
39	/** The selectable themes, in menu order. Labels are localized at render time (see {@link ThemeSelectorStrings}). */
40	export const THEMES: readonly ThemeOption[] = [
41	  { key: "rebrand", label: "Rebrand" },
42	  { key: "canvas", label: "Canvas" },
43	  { key: "canvasHighContrast", label: "Canvas high contrast" },
44	];
45	
46	/** Only rebrand ships light/dark values; the others are single-scheme. */
47	export const supportsScheme = (theme: PantokenTheme): boolean => theme === "rebrand";
48	
49	const STORAGE_KEY = "pantoken-theme";
50	
51	/** The persisted theme (default `rebrand`). */
52	export function getStoredTheme(): PantokenTheme {
53	  if (typeof localStorage === "undefined") return "rebrand";
54	  const value = localStorage.getItem(STORAGE_KEY);
55	  return THEMES.some((t) => t.key === value) ? (value as PantokenTheme) : "rebrand";
56	}
57	
58	// The reader's light/dark choice while on rebrand, remembered across a detour through a single-scheme
59	// theme so we can restore it when they switch back.
60	let rememberedDark: boolean | null = null;
61	
62	/** Post the active theme to every embedded demo runner so it re-themes its rendered result. */
63	export function broadcastTheme(theme: PantokenTheme): void {
64	  if (typeof document === "undefined") return;
65	  for (const frame of document.querySelectorAll<HTMLIFrameElement>(".pantoken-demo__frame")) {
66	    frame.contentWindow?.postMessage({ type: "pantoken-demo-theme", theme }, "*");
67	  }
68	}
69	
70	/**
71	 * Apply a theme: set the root attribute, persist it, gate light/dark (single-scheme themes force
72	 * light and hide the appearance toggle via CSS), and broadcast to the demos.
73	 */
74	export function applyTheme(theme: PantokenTheme): void {
75	  if (typeof document === "undefined") return;
76	  const html = document.documentElement;
77	  html.dataset.pantokenTheme = theme;
78	  try {
79	    localStorage.setItem(STORAGE_KEY, theme);
80	  } catch {
81	    // Private mode / storage disabled — the attribute still applies for this session.
82	  }
83	  if (supportsScheme(theme)) {
84	    // Restore the light/dark choice we stashed when leaving rebrand.
85	    if (rememberedDark !== null) {
86	      html.classList.toggle("dark", rememberedDark);
87	      rememberedDark = null;
88	    }
89	  } else {
90	    if (rememberedDark === null) rememberedDark = html.classList.contains("dark");
91	    html.classList.remove("dark");
92	  }
93	  broadcastTheme(theme);
94	}
